package com.aadil.ecommerce.security;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.security.authentication.AuthenticationProvider;import org.springframework.security.authentication.dao.DaoAuthenticationProvider;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;@Configuration@EnableWebSecuritypublic class SecurityConfiguration {    @Bean    public PasswordEncoder passwordEncoder(){        return new BCryptPasswordEncoder();    }    @Bean    public SecurityFilterChain securityFilterChain (HttpSecurity httpSecurity) throws Exception{        httpSecurity.csrf(AbstractHttpConfigurer::disable).sessionManagement(session->session.sessionCreationPolicy                (SessionCreationPolicy.STATELESS)).authorizeHttpRequests(auth->                auth.requestMatchers("/api/auth/**").permitAll().anyRequest().authenticated());       return httpSecurity.build();    }    @Bean    public AuthenticationManager authenticationManager (AuthenticationConfiguration authenticationConfiguration) throws Exception{        return authenticationConfiguration.getAuthenticationManager();    }    @Bean    public AuthenticationProvider authenticationProvider (UserDetailsService userDetailsService, PasswordEncoder passwordEncoder) throws Exception{        DaoAuthenticationProvider authenticationProvider = new DaoAuthenticationProvider(userDetailsService);        authenticationProvider.setPasswordEncoder(passwordEncoder);        return authenticationProvider;    }}